    ('67f6b622-7e3e-56f3-a771-04a4c3b9f29b', '0ee00df6-303f-5ba8-bf98-96ae46012c4d', 1, 'What did the council originally plan to do with the building?', '[{"optionKey":"A","content":"Sell it to a property developer","sortOrder":1},{"optionKey":"B","content":"Pull it down","sortOrder":2},{"optionKey":"C","content":"Turn it into offices","sortOrder":3}]'::jsonb,
