    ('aa5c486b-9d15-5db1-b0e5-1b5619417a4c', 'f0ab97d2-f0f9-540c-af4f-fe12ba2b3b7c', 1, 'What does the tutor suggest they mention as a limitation?', '[{"optionKey":"A","content":"Payment does not guarantee equal motivation","sortOrder":1},{"optionKey":"B","content":"The word list was too long","sortOrder":2},{"optionKey":"C","content":"The test was too easy","sortOrder":3}]'::jsonb,
