    ('d7b7c253-bee0-582a-97e1-4d07483efe2a', 'aaeaf2ef-ad99-5693-abba-5a9f3eba2cb6', 1, 'The entrance to a beaver''s lodge is above the water.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
