    ('55d2d2c6-8d13-5598-92c7-0ce72783e017', 'bc4e9a08-2ac4-546a-8f10-248100c52751', 1, 'Studies show that dams completely block the movement of large fish.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
