    ('7617a4a2-33e4-5d09-ab17-cc07edd3adf5', 'a6cb957c-f1c8-50fc-872f-afa919cab6d2', 1, 'Beavers have now been released in every part of Britain.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
