    ('7fd329ac-8f9f-5c89-a6b6-b807d20835d5', 'f7874eaa-9848-5832-9dcd-981f8dda5345', 1, 'What does the writer say about the claim that money cannot buy happiness?', '[{"optionKey":"A","content":"Research has proved that it is true","sortOrder":1},{"optionKey":"B","content":"It is repeated often, but research has not given a simple, consistent answer","sortOrder":2},{"optionKey":"C","content":"It is only ever quoted by advertisers","sortOrder":3},{"optionKey":"D","content":"It was first made in 2010","sortOrder":4}]'::jsonb,
     '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph A: the claim is repeated so often that it seems obvious, but the research is neither simple nor consistent.', 'PUBLISHED'),
    ('e68d5bd0-92cc-545f-aa44-25d21115256a', '173b89ac-13b7-57aa-874a-3a85d3104b69', 1, 'According to the study published in 2010, happiness in daily life ...', '[{"optionKey":"A","content":"rose with income without any limit","sortOrder":1},{"optionKey":"B","content":"rose with income only up to a certain level","sortOrder":2},{"optionKey":"C","content":"had no link with income","sortOrder":3},{"optionKey":"D","content":"fell as income rose","sortOrder":4}]'::jsonb,
     '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph A: it rose with income only up to a certain level.', 'PUBLISHED'),
    ('4c7a59a5-4017-500c-a847-b544280212fb', '5d7b914f-003e-5e53-82cb-df4faffc9d1d', 1, 'What did the researchers who re-examined the figures suggest?', '[{"optionKey":"A","content":"The 2010 study was completely wrong","sortOrder":1},{"optionKey":"B","content":"Extra money made no difference for a minority who were already unhappy","sortOrder":2},{"optionKey":"C","content":"Rich people are always unhappier","sortOrder":3},{"optionKey":"D","content":"The data sets were too small","sortOrder":4}]'::jsonb,
     '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph B: for a minority who were already unhappy, extra money made no difference.', 'PUBLISHED'),
    ('ef626edd-3141-5414-9ffa-6ab2b9899c4d', 'efacc7b3-8c44-5aab-aa39-2ffc0ede0bbd', 1, 'According to paragraph C, income has a stronger link with ...', '[{"optionKey":"A","content":"emotional wellbeing","sortOrder":1},{"optionKey":"B","content":"life evaluation","sortOrder":2},{"optionKey":"C","content":"relationships","sortOrder":3},{"optionKey":"D","content":"leisure time","sortOrder":4}]'::jsonb,
     '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph C: income has a stronger link with life evaluation than with emotional wellbeing.', 'PUBLISHED'),
    ('cc1290a0-bc53-5de1-873e-4057e5bf9627', '3591dfda-54c8-53da-b6de-2a544eb311c8', 1, 'What is meant by ''diminishing returns'' in paragraph D?', '[{"optionKey":"A","content":"People spend less money","sortOrder":1},{"optionKey":"B","content":"The benefit of extra money becomes smaller for people who are already comfortable","sortOrder":2},{"optionKey":"C","content":"Prices go up","sortOrder":3},{"optionKey":"D","content":"Companies make less profit","sortOrder":4}]'::jsonb,
     '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph D: for those already comfortable, extra money has a small effect.', 'PUBLISHED'),
    ('282afe1b-6708-5f92-bf93-cb12fb3f8918', '3aa0b874-48fe-5304-8f06-07a13077dc6f', 1, 'Researchers agree that happiness stops rising at a certain level of income.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
     '{"type":"CHOICE","correct":"NO"}'::jsonb, 1, 'Paragraph B: more recent work found no sign of a limit.', 'PUBLISHED'),
    ('ff1b1dc1-ba94-596e-ad29-6bcf753df66d', 'f0588d43-f926-50cf-9540-a03a379594be', 1, 'A pay rise matters less to a person if colleagues receive the same rise.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
     '{"type":"CHOICE","correct":"YES"}'::jsonb, 1, 'Paragraph D: a pay rise matters less if colleagues have received the same.', 'PUBLISHED'),
    ('1e11d812-6927-55c1-b15d-4469f6a950a3', 'bfb23671-1cb0-571e-b042-2aa74085240d', 1, 'Spending money on other people generally makes people happier than buying things for themselves.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
     '{"type":"CHOICE","correct":"YES"}'::jsonb, 1, 'Paragraph E: those who spend money on other people are generally happier.', 'PUBLISHED'),
    ('7190b117-d0f1-59b5-a6da-835a90483ab0', 'adef6066-fba4-5ade-9e24-bd33ebfd7b9f', 1, 'Governments should stop trying to raise the incomes of the poorest.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
