    ('2daf5c87-8a4b-5efb-8a1d-fc7ddf0571a6', '25f39762-5d15-52ab-aa33-9e382e4cac4b', 1, 'Wealthy societies become less happy as they grow richer.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb,
