    ('e14a86b8-179c-5ccb-8bbe-ca6dea2c54e7', 'c5874521-a15c-5a12-bac6-340e06b15263', 1, 'The table below shows the percentage of household waste that was recycled in four countries in 2000, 2010 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.', NULL,
     '{"type":"ESSAY","task":"TASK_1","minWords":150,"passBand":5.5,"chartFacts":"Percentage of household waste recycled in four countries (A to D) in 2000, 2010 and 2020. Country A: 12, 28, 46. Country B: 35, 41, 44. Country C: 5, 14, 31. Country D: 22, 19, 24. Key features: Country A showed the biggest rise (12% to 46%, nearly four times) and had the highest rate in 2020; Country B started highest in 2000 (35%) but grew slowly to 44%; Country C started lowest (5%) and rose more than six times to 31%; Country D was the only country with a fall (22% to 19% between 2000 and 2010) and had the lowest rate in 2020 (24%)."}'::jsonb, 1, 'Graded by the placement essay grader.', 'PUBLISHED'),
    ('916f8be0-75d0-5bcf-b288-6d646ce54968', 'fafd7d58-26c8-5814-ba47-bb4880de9c29', 1, 'Some people believe that the best way to reduce traffic in cities is to make public transport free. Others think that there are better ways to solve the problem. Discuss both views and give your own opinion. Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', NULL,
