INSERT INTO content_sections (id, package_version_id, title, skill, sort_order, time_limit_seconds, instructions) VALUES
    ('ff782da8-cbe2-55ce-82be-4dd29d4dc710', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Listening Part 1: booking a cooking course', 'LISTENING', 1, NULL, 'Questions 1–10. Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer. For question 6, choose A, B or C.'),
    ('b8a04739-ed17-587a-8321-9caa7d31c4a9', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Listening Part 2: the opening of a community arts centre', 'LISTENING', 2, NULL, 'Questions 11–20. Choose the correct letter, A, B or C, or write ONE WORD AND/OR A NUMBER where you see a line.'),
    ('c8ed7a6c-daca-5426-b002-174447b750aa', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Listening Part 3: a project on sleep and memory', 'LISTENING', 3, NULL, 'Questions 21–26: Choose the correct letter, A, B or C. Questions 27–30: Who will do each task? Choose A (Priya), B (Jack) or C (both of them).'),
    ('2145bd55-690e-5a63-ac72-d1852217b6b1', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Listening Part 4: the history of paper', 'LISTENING', 4, NULL, 'Questions 31–40. Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.'),
    ('d7ea35e2-0bce-5603-ab4e-f49ba314349c', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Reading Passage 1: the return of the beaver', 'READING', 5, 1200, 'Questions 1–6: Do the statements agree with the information in the passage? Choose TRUE, FALSE or NOT GIVEN. Questions 7–13: Complete the sentences. Choose NO MORE THAN TWO WORDS from the passage for each answer. You should spend about 20 minutes on this passage.'),
    ('6af9b328-5547-5fa0-ace6-22a27b9bcd5a', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Reading Passage 2: the economics of coffee', 'READING', 6, 1200, 'Questions 14–19: Choose the correct heading for each paragraph from the list of headings i–viii. Questions 20–23: Which paragraph, A–F, contains the following information? Questions 24–26: Complete the sentences. Choose ONE WORD ONLY from the passage. You should spend about 20 minutes on this passage.'),
    ('eff5d3ef-78d6-52fa-87c5-25cda7a1a5ae', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Reading Passage 3: does money buy happiness?', 'READING', 7, 1200, 'Questions 27–31: Choose the correct letter, A, B, C or D. Questions 32–36: Do the statements agree with the views of the writer? Choose YES, NO or NOT GIVEN. Questions 37–40: Complete the sentences. Choose ONE WORD ONLY from the passage. You should spend about 20 minutes on this passage.'),
    ('ec6df5c9-ae17-5596-87c2-d823bd2114de', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Writing Task 1: household waste recycling', 'WRITING', 8, 1200, 'Spend about 20 minutes on this task. Write at least 150 words.'),
    ('4d91dfba-4a64-5748-b71a-7c5071a4167f', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Writing Task 2: free public transport', 'WRITING', 9, 2400, 'Spend about 40 minutes on this task. Write at least 250 words.'),
    ('2623b4c8-a363-5a98-9fbd-babd460808cd', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Speaking Part 1: hometown and reading', 'SPEAKING', 10, NULL, 'The examiner asks general questions about yourself and familiar topics. Answer each question in a few sentences.'),
    ('3e611cff-9020-53f9-b7c0-7a4aa190bc26', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Speaking Part 2: a skill you would like to learn', 'SPEAKING', 11, NULL, 'You have one minute to prepare, then speak for one to two minutes.'),
    ('39330148-009b-5857-85aa-b07435e85af5', 'f0f5a9e3-526e-5894-93bb-2e4c01189fc1', 'Speaking Part 3: discussion', 'SPEAKING', 12, NULL, 'The examiner asks broader questions linked to the Part 2 topic. Give full answers with reasons and examples.');

